// This file is generated by `npm run import:videos`.
// Do not add secrets or unlicensed media.
const assetRoot = globalThis.location?.protocol === 'file:' ? './public' : '.';
const records = [];
export const localMedia = records.map(item => ({
  ...item,
  image: item.image.replace(/^\./, assetRoot),
  backdrop: item.backdrop.replace(/^\./, assetRoot),
  sources: item.sources.map(source => ({...source, url: source.url.replace(/^\./, assetRoot)})),
}));
